30	export class AgentConversationService extends EventTarget {
31	    private runningAgents: RunningAgent[]
32	
33	    constructor() {
34	        super()
35	        this.runningAgents = []
36	        register('agentConversationService', this)
37	    }
38	
39	    getRunningAgents() {
40	        return this.runningAgents
41	    }
42	
43	    observeRunEvent(event: AgentRunEvent, label: string) {
44	        if (event.type === 'started') {
45	            if (!this.runningAgents.some((agent) => agent.id === event.runId)) {
46	                this.setRunningAgents([...this.runningAgents, { id: event.runId, label }])
47	            }
48	
49	            return
50	        }
51	
52	        if (event.type === 'closed') this.removeRunningAgent(event.runId)
53	    }
54	
55	    subscribe(listener: Listener) {
56	        this.addEventListener('changed', listener)
57	
58	        return () => this.removeEventListener('changed', listener)
59	    }
60	
61	    private setRunningAgents(runningAgents: RunningAgent[]) {
62	        this.runningAgents = runningAgents
63	        this.dispatchEvent(new CustomEvent('changed'))
64	    }
65	
66	    private removeRunningAgent(runId: string) {
67	        this.setRunningAgents(this.runningAgents.filter((agent) => agent.id !== runId))
68	    }
69	}
