1	const { normalizeAgentTokenUsage } = require('../../../../shared/agent_usage_math.mjs');
2	const { normalizeChangedPaths, normalizedContent } = require('./agent_event_utils');
3	
4	const CLAUDE_FILE_TOOLS = new Set(['Edit', 'MultiEdit', 'NotebookEdit', 'Write']);
5	
6	/**
7	 * Claude speaks the same stream-json wire format on both the one-shot and the streaming path, so
8	 * every decoder here is shared by `agent_provider_protocol` and `ClaudeStreamingAdapter`. Keep it
9	 * that way: a decoder that lives in only one of them silently gives the two paths different output
10	 * for identical agent behaviour.
11	 */
12	function claudeAssistantText(event) {
13	    if (event.type !== 'assistant' || !Array.isArray(event.message?.content)) return '';
14	
15	    return event.message.content
16	        .filter(({ type }) => type === 'text')
17	        .map(({ text }) => text)
18	        .filter((text) => typeof text === 'string')
19	        .join('');
20	}
21	
22	function claudeChangedPaths(event, rootPath) {
23	    if (event.type !== 'assistant' || !Array.isArray(event.message?.content)) return [];
24	
25	    const filePaths = event.message.content
26	        .filter((block) => block?.type === 'tool_use' && CLAUDE_FILE_TOOLS.has(block.name))
27	        .map(({ input, name }) => name === 'NotebookEdit' ? input?.notebook_path : input?.file_path);
28	
29	    return normalizeChangedPaths(rootPath, filePaths);
30	}
31	
32	/** Tool calls and their results, so the transcript shows what ran as well as what came back. */
33	function claudeTranscriptEvents(event) {
34	    if (!Array.isArray(event.message?.content)) return [];
35	    if (event.type === 'assistant') {
36	        return event.message.content
37	            .filter((block) => block?.type === 'tool_use')
38	            .map((block) => ({ content: JSON.stringify(block.input ?? {}), toolType: `tool.${block.name}` }));
39	    }
40	    if (event.type === 'user') {
41	        return event.message.content
42	            .filter((block) => block?.type === 'tool_result')
43	            .map((block) => ({ content: normalizedContent(block.content), toolType: 'tool.result' }))
44	            .filter(({ content }) => content !== null);
45	    }
46	
47	    return [];
48	}
49	
50	// Claude folds thinking into output_tokens, so reasoningTokens is always 0, and reports cache
51	// creation and cache reads as buckets alongside a cache-free input_tokens.
52	function claudeUsage(event) {
53	    if (event.type !== 'result' || !event.usage || typeof event.usage !== 'object' || Array.isArray(event.usage)) return null;
54	
55	    return normalizeAgentTokenUsage({
56	        cachedInputTokens: (event.usage.cache_creation_input_tokens ?? 0) + (event.usage.cache_read_input_tokens ?? 0),
57	        costUsd: event.total_cost_usd,
58	        inputTokens: event.usage.input_tokens,
59	        outputTokens: event.usage.output_tokens,
60	        reasoningTokens: 0,
61	    });
62	}
63	
64	module.exports = { claudeAssistantText, claudeChangedPaths, claudeTranscriptEvents, claudeUsage };
65

1	const { normalizedContent } = require('./agent_event_utils');
2	const { claudeChangedPaths, claudeUsage } = require('./agent_claude_events');
3	const { isMissingSession } = require('./agent_provider_protocol');
4	
5	const CLAUDE_APPROVAL_DECISIONS = ['accept', 'acceptForSession', 'decline', 'cancel'];
6	const CLAUDE_FILE_TOOLS = new Set(['Edit', 'MultiEdit', 'NotebookEdit', 'Write']);
7	const CLAUDE_QUESTION_TOOL = 'AskUserQuestion';
8	
9	function requireMessage(content) {
10	    if (typeof content !== 'string' || content.trim().length === 0) throw new Error('Streaming agent message is required');
11	
12	    return content;
13	}
14	
15	function claudeUserMessage(content) {
16	    return { message: { content, role: 'user' }, type: 'user' };
17	}
18	
19	function claudeControlResponse(requestId, response) {
20	    return {
21	        response: { request_id: requestId, response, subtype: 'success' },
22	        type: 'control_response',
23	    };
24	}
25	
26	function claudeQuestionRequest(event) {
27	    if (event.type !== 'control_request' || event.request?.subtype !== 'can_use_tool') return null;
28	    if (event.request.tool_name !== CLAUDE_QUESTION_TOOL || !Array.isArray(event.request.input?.questions)) return null;
29	
30	    const questions = event.request.input.questions.map((question, index) => ({
31	        ...question,
32	        id: question.id ?? `claude-question-${index}`,
33	    }));
34	
35	    return {
36	        input: event.request.input,
37	        questions,
38	        requestId: event.request_id,
39	        toolUseId: event.request.tool_use_id,
40	    };
41	}
42	
43	function approvalFilePaths(toolName, input) {
44	    if (!CLAUDE_FILE_TOOLS.has(toolName) || !input || typeof input !== 'object' || Array.isArray(input)) return [];
45	    const filePath = toolName === 'NotebookEdit' ? input.notebook_path : input.file_path;
46	
47	    return typeof filePath === 'string' && filePath.length > 0 ? [filePath] : [];
48	}
49	
50	function claudeApprovalRequest(event) {
51	    if (event.type !== 'control_request' || event.request?.subtype !== 'can_use_tool') return null;
52	    if (event.request.tool_name === CLAUDE_QUESTION_TOOL) return null;
53	    const { input, permission_suggestions: permissionSuggestions, tool_name: toolName, tool_use_id: toolUseId } = event.request;
54	    if (event.request_id === undefined || event.request_id === null) throw new Error('Missing Claude approval request id');
55	    if (typeof toolName !== 'string' || toolName.length === 0) throw new Error('Missing Claude approval tool name');
56	    if (typeof toolUseId !== 'string' || toolUseId.length === 0) throw new Error('Missing Claude approval tool use id');
57	    if (!input || typeof input !== 'object' || Array.isArray(input)) throw new Error('Missing Claude approval input');
58	    if (permissionSuggestions !== undefined && !Array.isArray(permissionSuggestions)) {
59	        throw new Error('Invalid Claude approval permission suggestions');
60	    }
61	    const availableDecisions = permissionSuggestions?.length > 0
62	        ? CLAUDE_APPROVAL_DECISIONS
63	        : CLAUDE_APPROVAL_DECISIONS.filter((decision) => decision !== 'acceptForSession');
64	    const approval = {
65	        approvalId: toolUseId,
66	        availableDecisions,
67	        command: toolName === 'Bash' && typeof input.command === 'string' ? input.command : null,
68	        cwd: typeof input.cwd === 'string' ? input.cwd : null,
69	        filePaths: approvalFilePaths(toolName, input),
70	        input: structuredClone(input),
71	        itemId: toolUseId,
72	        kind: toolName === 'Bash' ? 'commandExecution' : CLAUDE_FILE_TOOLS.has(toolName) ? 'fileChange' : 'toolUse',
73	        permissionSuggestions: structuredClone(permissionSuggestions ?? []),
74	        provider: 'claude',
75	        reason: event.request.decision_reason ?? event.request.reason ?? null,
76	        requestId: event.request_id,
77	        startedAtMs: Date.now(),
78	        toolName,
79	    };
80	
81	    return { approval, input, permissionSuggestions: permissionSuggestions ?? [], toolUseId };
82	}
83	
84	function claudeApprovalResponse(pendingApproval, decision) {
85	    const { input, permissionSuggestions, toolUseId } = pendingApproval;
86	    if (decision === 'accept') return { behavior: 'allow', toolUseID: toolUseId, updatedInput: input };
87	    if (decision === 'acceptForSession') {
88	        return {
89	            behavior: 'allow',
90	            toolUseID: toolUseId,
91	            updatedInput: input,
92	            updatedPermissions: permissionSuggestions,
93	        };
94	    }
95	    if (decision === 'decline') {
96	        return { behavior: 'deny', message: 'User declined this tool request', toolUseID: toolUseId };
97	    }
98	
99	    return { behavior: 'deny', interrupt: true, message: 'User stopped the turn', toolUseID: toolUseId };
100	}
101	
102	function isClaudeMissingSessionResult(event, providerConversationId) {
103	    if (!providerConversationId || event.type !== 'result' || event.is_error !== true) return false;
104	    if (event.session_id !== providerConversationId || !Array.isArray(event.errors)) return false;
105	
106	    return event.errors.includes(`No conversation found with session ID: ${providerConversationId}`);
107	}
108	
109	function eventBase(providerItemId, type, label, status = 'inProgress') {
110	    return { content: '', label, providerItemId, status, type };
111	}
112	
113	function toolInputContent(input) {
114	    if (typeof input === 'string') return input;
115	
116	    return JSON.stringify(input ?? {});
117	}
118	
119	function claudeToolEvent(block, status = 'inProgress', providerItemId = block.id) {
120	    const base = eventBase(providerItemId, `tool.${block.name}`, block.name, status);
121	    if (block.name === 'Bash') {
122	        return {
123	            ...base,
124	            command: block.input?.command,
125	            content: block.input?.command ?? toolInputContent(block.input),
126	            label: block.input?.command ?? 'Bash',
127	            type: 'commandExecution',
128	            workingDirectory: block.input?.cwd,
129	        };
130	    }
131	    if (CLAUDE_FILE_TOOLS.has(block.name)) {
132	        const filePaths = approvalFilePaths(block.name, block.input);
133	        const content = typeof block.input === 'string' ? block.input : filePaths.join('\n');
134	
135	        return { ...base, content, label: block.name, type: 'fileChange' };
136	    }
137	
138	    return { ...base, content: toolInputContent(block.input) };
139	}
140	
141	class ClaudeStreamingAdapter {
142	    constructor(writeLine, onEvent, rootPath, providerConversationId) {
143	        this.writeLine = writeLine;
144	        this.onEvent = onEvent;
145	        this.pendingApprovals = new Map();
146	        this.pendingQuestions = new Map();
147	        this.providerConversationId = providerConversationId;
148	        this.rootPath = rootPath;
149	        this.activeBlocks = new Map();
150	        this.activeMessageId = null;
151	        this.diagnosticSequence = 1;
152	        this.turnStarted = false;
153	        this.turnHasAssistantText = false;
154	    }
155	
156	    async start(prompt) {
157	        await this.sendMessage(prompt);
158	    }
159	
160	    async sendMessage(content) {
161	        await this.writeLine(claudeUserMessage(requireMessage(content)));
162	    }
163	
164	    async answerQuestion(requestId, answers) {
165	        const pendingQuestion = this.pendingQuestions.get(requestId);
166	        if (!pendingQuestion) throw new Error(`Unknown Claude question request id: ${requestId}`);
167	        const mappedAnswers = Object.fromEntries(pendingQuestion.questions.map(({ id, question }) => {
168	            if (!Object.hasOwn(answers, id)) throw new Error(`Missing answer for Claude question: ${id}`);
169	
170	            return [question, answers[id]];
171	        }));
172	        const updatedInput = { ...pendingQuestion.input, answers: mappedAnswers };
173	        const response = { behavior: 'allow', toolUseID: pendingQuestion.toolUseId, updatedInput };
174	        await this.writeLine(claudeControlResponse(requestId, response));
175	        this.pendingQuestions.delete(requestId);
176	    }
177	
178	    async answerApproval(requestId, decision) {
179	        const pendingApproval = this.pendingApprovals.get(requestId);
180	        if (!pendingApproval) throw new Error(`Unknown or stale Claude approval request id: ${requestId}`);
181	        if (pendingApproval.submitted) throw new Error(`Claude approval request was already submitted: ${requestId}`);
182	        if (!pendingApproval.approval.availableDecisions.includes(decision)) {
183	            throw new Error(`Unsupported Claude approval decision for request ${requestId}`);
184	        }
185	        const response = claudeApprovalResponse(pendingApproval, decision);
186	        pendingApproval.submitted = true;
187	        try {
188	            await this.writeLine(claudeControlResponse(requestId, response));
189	        } catch (error) {
190	            pendingApproval.submitted = false;
191	            throw error;
192	        }
193	        await this.onEvent({ requestId, type: 'approvalSubmitted' });
194	        this.pendingApprovals.delete(requestId);
195	        await this.onEvent({ requestId, type: 'approvalResolved' });
196	    }
197	
198	    async handleMessage(event) {
199	        const questionRequest = claudeQuestionRequest(event);
200	        if (questionRequest) {
201	            this.pendingQuestions.set(questionRequest.requestId, questionRequest);
202	            await this.onEvent({
203	                questions: questionRequest.questions,
204	                requestId: questionRequest.requestId,
205	                type: 'question',
206	            });
207	            return;
208	        }
209	        const approvalRequest = claudeApprovalRequest(event);
210	        if (approvalRequest) {
211	            if (this.pendingApprovals.has(approvalRequest.approval.requestId)) {
212	                throw new Error(`Duplicate Claude approval request id: ${approvalRequest.approval.requestId}`);
213	            }
214	            this.pendingApprovals.set(approvalRequest.approval.requestId, { ...approvalRequest, submitted: false });
215	            await this.onEvent({ approval: approvalRequest.approval, type: 'approval' });
216	            return;
217	        }
218	        if (event.type === 'control_request' && event.request?.subtype === 'can_use_tool') {
219	            throw new Error('Invalid Claude question request');
220	        }
221	        if (event.type === 'system' && typeof event.session_id === 'string') {
222	            await this.onEvent({ conversationId: event.session_id, type: 'sessionStarted' });
223	        }
224	        if (event.type === 'system') {
225	            if (event.subtype !== 'init') await this.emitDiagnostic(`Claude system event: ${event.subtype ?? 'unknown'}`);
226	            return;
227	        }
228	        if (event.type === 'stream_event') {
229	            await this.handleStreamEvent(event.event);
230	            return;
231	        }
232	        if (event.type === 'assistant') {
233	            await this.handleAssistantCompletion(event);
234	            return;
235	        }
236	        if (event.type === 'user') {
237	            await this.ensureTurnStarted();
238	            await this.handleToolResults(event);
239	            return;
240	        }
241	        if (event.type === 'result') {
242	            await this.handleResult(event);
243	            return;
244	        }
245	        await this.emitDiagnostic(`unsupported Claude event: ${event.type ?? 'unknown'}`);
246	    }
247	
248	    async ensureTurnStarted() {
249	        if (this.turnStarted) return;
250	        this.turnStarted = true;
251	        await this.onEvent({ type: 'turnStarted' });
252	    }
253	
254	    async handleStreamEvent(streamEvent) {
255	        if (!streamEvent || typeof streamEvent.type !== 'string') {
256	            await this.emitDiagnostic('invalid stream event');
257	            return;
258	        }
259	        if (streamEvent.type === 'message_start') {
260	            await this.ensureTurnStarted();
261	            this.activeMessageId = streamEvent.message?.id;
262	            this.activeBlocks.clear();
263	            if (typeof this.activeMessageId !== 'string' || this.activeMessageId.length === 0) {
264	                await this.emitDiagnostic('message_start missing message id');
265	            }
266	            return;
267	        }
268	        if (streamEvent.type === 'content_block_start') {
269	            await this.handleContentBlockStart(streamEvent);
270	            return;
271	        }
272	        if (streamEvent.type === 'content_block_delta') {
273	            await this.handleContentBlockDelta(streamEvent);
274	            return;
275	        }
276	        if (streamEvent.type === 'content_block_stop' || streamEvent.type === 'message_delta' || streamEvent.type === 'message_stop') return;
277	        await this.emitDiagnostic(`unsupported stream event: ${streamEvent.type}`);
278	    }
279	
280	    async handleContentBlockStart(streamEvent) {
281	        if (!Number.isSafeInteger(streamEvent.index) || !streamEvent.content_block || typeof this.activeMessageId !== 'string') {
282	            await this.emitDiagnostic('invalid content_block_start');
283	            return;
284	        }
285	        const block = structuredClone(streamEvent.content_block);
286	        const providerItemId = block.id ?? `${this.activeMessageId}:${block.type}:${streamEvent.index}`;
287	        const separator = block.type === 'text' && this.turnHasAssistantText ? '\n\n' : '';
288	        const trackedBlock = { block, inputJson: '', providerItemId, separator, text: block.text ?? block.thinking ?? '' };
289	        this.activeBlocks.set(streamEvent.index, trackedBlock);
290	        if (block.type === 'text') {
291	            await this.onEvent({ itemId: providerItemId, type: 'assistantStarted' });
292	            if (separator.length > 0) await this.onEvent({ content: separator, itemId: providerItemId, type: 'assistant' });
293	            return;
294	        }
295	        if (block.type === 'thinking') {
296	            const event = {
297	                ...eventBase(providerItemId, 'reasoning', 'Thinking'),
298	                content: trackedBlock.text,
299	                details: [trackedBlock.text],
300	                summary: [],
301	            };
302	            await this.onEvent({ event, type: 'event' });
303	            return;
304	        }
305	        if (block.type === 'tool_use') await this.onEvent({ event: claudeToolEvent(block, 'inProgress', providerItemId), type: 'event' });
306	    }
307	
308	    async handleContentBlockDelta(streamEvent) {
309	        const trackedBlock = this.activeBlocks.get(streamEvent.index);
310	        if (!trackedBlock || !streamEvent.delta || typeof streamEvent.delta.type !== 'string') {
311	            await this.emitDiagnostic('invalid content_block_delta');
312	            return;
313	        }
314	        const { delta } = streamEvent;
315	        if (delta.type === 'text_delta' && typeof delta.text === 'string' && trackedBlock.block.type === 'text') {
316	            trackedBlock.text += delta.text;
317	            this.turnHasAssistantText = this.turnHasAssistantText || delta.text.length > 0;
318	            await this.onEvent({ content: delta.text, itemId: trackedBlock.providerItemId, type: 'assistant' });
319	            return;
320	        }
321	        if (delta.type === 'thinking_delta' && typeof delta.thinking === 'string' && trackedBlock.block.type === 'thinking') {
322	            trackedBlock.text += delta.thinking;
323	            const event = {
324	                ...eventBase(trackedBlock.providerItemId, 'reasoning', 'Thinking'),
325	                content: trackedBlock.text,
326	                details: [trackedBlock.text],
327	                summary: [],
328	            };
329	            await this.onEvent({ event, type: 'event' });
330	            return;
331	        }
332	        if (delta.type === 'input_json_delta' && typeof delta.partial_json === 'string' && trackedBlock.block.type === 'tool_use') {
333	            trackedBlock.inputJson += delta.partial_json;
334	            const updatedBlock = { ...trackedBlock.block, input: trackedBlock.inputJson };
335	            await this.onEvent({ event: claudeToolEvent(updatedBlock, 'inProgress', trackedBlock.providerItemId), type: 'event' });
336	            return;
337	        }
338	        if (delta.type !== 'signature_delta') await this.emitDiagnostic(`unsupported content delta: ${delta.type}`);
339	    }
340	
341	    async handleAssistantCompletion(event) {
342	        await this.ensureTurnStarted();
343	        if (!Array.isArray(event.message?.content)) {
344	            await this.emitDiagnostic('assistant message missing content');
345	            return;
346	        }
347	        const messageId = event.message.id ?? this.activeMessageId;
348	        if (typeof messageId !== 'string' || messageId.length === 0) throw new Error('Missing Claude assistant message id');
349	        for (const [index, block] of event.message.content.entries()) {
350	            const providerItemId = block.id ?? `${messageId}:${block.type}:${index}`;
351	            if (block.type === 'text' && typeof block.text === 'string') {
352	                const trackedBlock = this.activeBlocks.get(index);
353	                const separator = trackedBlock?.separator ?? (this.turnHasAssistantText ? '\n\n' : '');
354	                if (!trackedBlock || trackedBlock.providerItemId !== providerItemId) {
355	                    await this.onEvent({ itemId: providerItemId, type: 'assistantStarted' });
356	                }
357	                this.turnHasAssistantText = this.turnHasAssistantText || block.text.length > 0;
358	                await this.onEvent({ content: `${separator}${block.text}`, itemId: providerItemId, type: 'assistantCompleted' });
359	                continue;
360	            }
361	            if (block.type === 'thinking') {
362	                const content = typeof block.thinking === 'string' ? block.thinking : '';
363	                const reasoningEvent = {
364	                    ...eventBase(providerItemId, 'reasoning', 'Thinking', 'completed'),
365	                    content,
366	                    details: [content],
367	                    summary: [],
368	                };
369	                await this.onEvent({ event: reasoningEvent, type: 'event' });
370	                continue;
371	            }
372	            if (block.type === 'tool_use') await this.onEvent({ event: claudeToolEvent(block, 'inProgress', providerItemId), type: 'event' });
373	        }
374	        const changedPaths = claudeChangedPaths(event, this.rootPath);
375	        if (changedPaths.length > 0) await this.onEvent({ paths: changedPaths, type: 'changedPaths' });
376	    }
377	
378	    async handleToolResults(event) {
379	        if (!Array.isArray(event.message?.content)) return;
380	        for (const block of event.message.content) {
381	            if (block?.type !== 'tool_result' || typeof block.tool_use_id !== 'string') continue;
382	            const trackedTool = [...this.activeBlocks.values()].find(({ providerItemId }) => providerItemId === block.tool_use_id);
383	            const toolEvent = trackedTool?.block?.type === 'tool_use'
384	                ? claudeToolEvent(trackedTool.block, block.is_error ? 'failed' : 'completed')
385	                : eventBase(block.tool_use_id, 'tool.result', 'Tool result', block.is_error ? 'failed' : 'completed');
386	            toolEvent.output = normalizedContent(block.content) ?? '';
387	            await this.onEvent({ event: toolEvent, type: 'event' });
388	        }
389	    }
390	
