31	function handleAssistantStarted(service, run, event, timestamp) {
32	    const item = startAssistantItem(run, requireString(event.itemId, 'assistant item id'), timestamp);
33	    emitRunEvent(run, { content: '', messageId: item.messageId, sequence: item.sequence, type: 'output' });
34	}
