36	function handleAssistant(service, run, event, timestamp) {
37	    const safeContent = redactSecrets(event.content, run.secretValues);
38	    const itemId = run.agent === 'codex'
39	        ? requireString(event.itemId, 'assistant item id')
40	        : event.itemId;
41	    const { message, segment } = appendAssistantOutput(run, safeContent, timestamp, itemId);
42	    if (segment.length > 0) {
43	        emitRunEvent(run, { content: segment, messageId: message.id, sequence: message.sequence, type: 'output' });
44	    }
45	}
