47	function handleAssistantCompleted(service, run, event, timestamp) {
48	    const safeContent = redactSecrets(event.content, run.secretValues);
49	    const itemId = requireString(event.itemId, 'assistant item id');
50	    const { message, previousContent, replaced } = replaceAssistantOutput(run, safeContent, timestamp, itemId);
51	    if (!replaced) return;
52	
53	    emitRunEvent(run, {
54	        content: safeContent,
55	        messageId: message.id,
56	        previousContent,
57	        replace: true,
58	        sequence: message.sequence,
59	        type: 'output',
60	    });
61	}
