67	/** Provider events are keyed by `providerItemId` so a later revision of the same item replaces its entry. */
68	function handleEvent(service, run, event, timestamp) {
69	    const safeEvent = redactConversationEvent(event.event, run.secretValues);
70	    const providerItemId = requireString(safeEvent.providerItemId, 'event providerItemId');
71	    const currentIndex = run.providerEventEntryIndexes.get(providerItemId);
72	    let eventEntry;
73	    if (currentIndex !== undefined) {
74	        const current = run.conversation.entries[currentIndex];
75	        eventEntry = createProviderEventEntry(safeEvent, current.id, timestamp, current.sequence);
76	        run.conversation.entries[currentIndex] = eventEntry;
77	    } else {
78	        const previousEntry = run.conversation.entries.at(-1);
79	        if (safeEvent.type === 'diagnostic' && previousEntry?.kind === 'event' && previousEntry.type === 'diagnostic') {
80	            eventEntry = appendDiagnosticContent(previousEntry, safeEvent.content);
81	            run.conversation.entries[run.conversation.entries.length - 1] = eventEntry;
82	        } else {
83	            const sequence = nextRunSequence(run);
84	            eventEntry = createProviderEventEntry(
85	                safeEvent,
86	                `${run.id}-event-${sequence}`,
87	                timestamp,
88	                sequence,
89	            );
90	            run.providerEventEntryIndexes.set(providerItemId, run.conversation.entries.length);
91	            run.conversation.entries.push(eventEntry);
92	        }
93	    }
94	    emitRunEvent(run, { event: eventEntry, type: 'agentEvent' });
95	}
