97	function handleTranscript(service, run, event, timestamp) {
98	    const safeContent = redactSecrets(event.content, run.secretValues);
99	    run.conversation.entries.push(createEventEntry(
100	        `${run.id}-provider-${run.conversation.entries.length}`,
101	        event.toolType,
102	        safeContent,
103	        timestamp,
104	        nextRunSequence(run),
105	    ));
106	}
