108	function handleError(service, run, event) {
109	    service.recordOutput(run.id, 'stderr', event.content);
110	}
111	
112	function handleFatal(service, run, event) {
113	    service.failStreamingRun(run, new Error(event.content));
114	}
115	
116	function handleSessionFailed(service, run, event) {
117	    run.missingSession = event.missingSession;
118	    service.failStreamingRun(run, new Error(event.content));
119	}
