121	async function handleQuestion(service, run, event) {
122	    run.conversation.status = 'waitingForInput';
123	    run.waitingForQuestion = true;
124	    run.pendingQuestions = event.questions;
125	    await service.persistCheckpoint(run);
126	    emitRunEvent(run, { questions: event.questions, requestId: event.requestId, state: 'waitingForInput', type: 'question' });
127	}
