129	async function handleApproval(service, run, event) {
130	    const requestId = event.approval.requestId;
131	    if (run.pendingApprovals.has(requestId)) throw new Error(`Duplicate agent approval request id: ${requestId}`);
132	    run.pendingApprovals.set(requestId, { ...event.approval, submitted: false });
133	    run.conversation.status = 'waitingForInput';
134	    await service.persistCheckpoint(run);
135	    emitRunEvent(run, { approval: event.approval, state: 'waitingForInput', type: 'approval' });
136	}
137	
138	function handleApprovalSubmitted(service, run, event) {
139	    const approval = run.pendingApprovals.get(event.requestId);
140	    if (!approval) return;
141	    approval.submitted = true;
142	    emitRunEvent(run, { requestId: event.requestId, type: 'approvalSubmitted' });
143	}
144	
145	function handleApprovalResolved(service, run, event) {
146	    if (!run.pendingApprovals.delete(event.requestId)) return;
147	    const state = hasPendingInteraction(run) ? 'waitingForInput' : 'running';
148	    run.conversation.status = state;
149	    emitRunEvent(run, { requestId: event.requestId, state, type: 'approvalResolved' });
150	    emitRunEvent(run, { state, type: 'state' });
151	}
