153	/**
154	 * End of a streaming turn: settle the assistant message, then either shut the process down,
155	 * send the message queued while the turn was running, or park the run waiting for input.
156	 */
157	async function handleTurnCompleted(service, run, event, timestamp) {
158	    completeAssistantOutput(run, timestamp);
159	    run.turnActive = false;
160	    run.waitingForQuestion = false;
161	    run.pendingApprovals.clear();
162	    run.missingSession = run.missingSession || event.missingSession;
163	    if (event.missingSession) run.finishing = true;
164	    if (event.usage) run.conversation.usage = accumulateUsage(run.conversation.usage, event.usage);
165	    if (event.error) {
166	        service.failStreamingRun(run, new Error(event.error));
167	        return;
168	    }
169	    if (run.finishing) {
170	        service.beginFinishShutdown(run);
171	        return;
172	    }
173	    if (run.queuedMessage) {
174	        const { content, revision } = run.queuedMessage;
175	        run.conversation.status = 'waitingForInput';
176	        await service.sendStreamingMessage(run, content);
177	        run.queuedMessage = null;
178	        run.sentQueuedMessageRevision = revision;
179	        return;
180	    }
181	    const synchronizedMessage = lastMessageEntry(run.conversation);
182	    if (synchronizedMessage) updateProviderSession(run, synchronizedMessage.id, timestamp);
183	    run.conversation.status = 'waitingForInput';
184	    run.conversation.completedAt = null;
185	    await service.persistCheckpoint(run);
186	    emitRunEvent(run, { state: 'waitingForInput', type: 'state' });
187	}
