189	/** Keyed by streaming event type; unknown types are ignored. Each handler takes `(service, run, event, timestamp)`. */
190	const STREAMING_EVENT_HANDLERS = {
191	    approval: handleApproval,
192	    approvalResolved: handleApprovalResolved,
193	    approvalSubmitted: handleApprovalSubmitted,
194	    assistant: handleAssistant,
195	    assistantCompleted: handleAssistantCompleted,
196	    assistantStarted: handleAssistantStarted,
197	    changedPaths: handleChangedPaths,
198	    error: handleError,
199	    event: handleEvent,
200	    fatal: handleFatal,
201	    question: handleQuestion,
202	    sessionFailed: handleSessionFailed,
203	    sessionStarted: handleSessionStarted,
204	    transcript: handleTranscript,
205	    turnCompleted: handleTurnCompleted,
206	    turnStarted: handleTurnStarted,
207	};
208	
209	module.exports = { STREAMING_EVENT_HANDLERS };
